import test from 'node:test';
import assert from 'node:assert/strict';
import {INITIAL,PLANS,simulate,compare,moveTask,validate} from './model.js';
import {definition,toToolState,fromToolState} from '../../../embed/definitions/lab-possibilities.js';
import {validateState,applyControl} from '../../../embed/core/schema.js';
const state=patch=>({...structuredClone(INITIAL),...patch});
test('prerequisites must be completed before work; skipped work does not retry or spend effort',()=>{const r=simulate(state({plan:['export','data']}));assert.deepEqual(r.trace.map(t=>t.status),['blocked','completed']);assert.equal(r.spent,3);assert.equal(r.delivered.length,0);assert.ok(r.reachable.some(t=>t.id==='export'));});
test('indivisible effort respects the budget but a later smaller task can still fit',()=>{const r=simulate(state({budget:2,plan:['data','report']}));assert.deepEqual(r.trace.map(t=>t.status),['over-budget','completed']);assert.equal(r.spent,2);assert.equal(r.remaining,0);});
test('dependency chain and permission jointly gate self service',()=>{const r=simulate(state({budget:30,plan:['data','connection','self']}));assert.equal(r.trace.at(-1).status,'blocked');assert.match(r.trace.at(-1).reason,/permission/);const ready=simulate(state({budget:30,plan:['data','connection','permission','self']}));assert.equal(ready.trace.at(-1).status,'completed');});
test('changing demand reverses which plan serves more distinct needs without assigning ROI',()=>{const current=state({demand:'current'}),future=state({demand:'future'});assert.ok(simulate(current).served.length>simulate({...current,plan:PLANS.enable}).served.length);assert.ok(simulate(future).served.length<simulate({...future,plan:PLANS.enable}).served.length);});
test('pinned order replays current estimates, demand and budget',()=>{const pin=state({budget:1,demand:'current'}),s=state({budget:30,demand:'mixed',costs:{...INITIAL.costs,data:1}});assert.deepEqual(compare(s,pin),simulate({...s,plan:pin.plan}));assert.equal(compare(s,pin).spent,6);});
test('moving a task changes prerequisite feasibility and never duplicates it',()=>{const s=state({plan:['export','data']});const next=moveTask(s,'data',0);assert.deepEqual(next.plan,['data','export']);assert.equal(simulate(next).delivered.length,1);assert.deepEqual(s.plan,['export','data']);});
test('strict validators reject invalid structures, duplicates, extras and effort bounds',()=>{for(const s of [null,state({surprise:true}),state({plan:['data','data']}),state({plan:['bad']}),state({budget:0}),state({costs:{...INITIAL.costs,data:NaN}}),state({costs:{...INITIAL.costs,extra:1}})])assert.throws(()=>validate(s));});
test('article actions, state handoff and narrow figure use the actual model',()=>{const s=state();validateState(definition,s);const next=applyControl(definition,s,'enable');assert.deepEqual(next.plan,PLANS.enable);assert.deepEqual(fromToolState(toToolState(next)),next);for(const width of [320,1100]){const out=definition.views.landscape.render(next,{width});assert.match(out.svg,/<svg/);assert.match(out.summary,/12 of 12 effort/);assert.ok(!out.svg.includes('undefined'));}});
